/**
 * @amc/prompt-families: TypeScript twin of `services/langgraph/agency/prompt_families`
 * (reusable prompt families, concept ledger, v10 prompt OS). Python is the
 * reference; `tests/fixtures/prompt-families-parity.json` is generated by
 * `services/langgraph/tests/test_prompt_families_parity_fixture.py`.
 *
 * Instances compile through `@amc/guidance`, so every family output ends at
 * PROMPT_PACKAGE_READY (or BLOCKED) and nothing executes: no media is
 * generated, no ad or product is created, nothing is published or spent. A
 * hook's creative score is never observed performance, `ComputationEvidence`
 * never upgrades a premise to VERIFIED, and a paid-media spec can never mutate a
 * platform (`execution` is `SPEC_ONLY`, `platform_mutation` is `false`).
 *
 * Left in Python: `resolve_functional_roles`, which needs the sealed RoleOS
 * registry. As in `@amc/guidance`, Pydantic's lax coercions are refused and the
 * UI/UX compiler is passed in as an adapter.
 */
export * from './models';
export * from './ledger';
export * from './roles';
export * from './capabilities';
export * from './compiler';
